#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/range_control/range_control.hpp"
#include "gui_forms/animation.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// SweepScope's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/sweep_scope.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The words drawn before the level's percentage.
template <typename Declaring>
struct SweepScopeCaptionCapability {
    PropertyCell<std::string, SweepScopeCaptionCapability<Declaring>> caption{std::string("LEVEL")};

    static void assign(SweepScopeCaptionCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.caption), incoming);
        if (!capability.caption.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.caption));
    }
};

// How long the sweep takes to cross the trace once, from 0.1 to 60 seconds (std::out_of_range outside them); the table value is in seconds.
template <typename Declaring>
struct SweepScopePeriodCapability {
    PropertyCell<FrameInterval, SweepScopePeriodCapability<Declaring>> sweep_period{std::chrono::microseconds(1'234'568)};

    static void assign(SweepScopePeriodCapability& capability, FrameInterval incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.sweep_period), incoming);
        if (!capability.sweep_period.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.sweep_period));
    }
};

// Every SweepScope capability, in the order the declaring class takes them.
template <typename Declaring>
struct SweepScopeCapabilities : public SweepScopeCaptionCapability<Declaring>,
                                public SweepScopePeriodCapability<Declaring> {};

} // namespace gui_forms
